<?php
require_once "config/db.php";$pageTitle='Reports';$rows=$pdo->query("SELECT m.*,COALESCE(p.name,'No plan') plan_name,COALESCE(p.price,0) plan_price FROM members m LEFT JOIN plans p ON p.id=m.plan_id ORDER BY m.name")->fetchAll();require "includes/header.php";
?><div class="page-intro no-print"><div><h1>Member report</h1><p>Consolidated overview of registered members and memberships.</p></div><button class="btn btn-primary" onclick="window.print()">⤓ Print / Save PDF</button></div><section class="panel"><div class="panel-head"><div><h3>Member directory</h3><p>Total records: <?= count($rows) ?></p></div><span class="tag">FITFLEX REPORT</span></div><div class="table-wrap"><table><thead><tr><th>NAME</th><th>EMAIL</th><th>PHONE</th><th>PLAN</th><th>PRICE</th><th>JOIN DATE</th><th>STATUS</th></tr></thead><tbody><?php foreach($rows as $m): ?><tr><td><?= htmlspecialchars($m['name']) ?></td><td><?= htmlspecialchars($m['email']) ?></td><td><?= htmlspecialchars($m['phone']) ?></td><td><?= htmlspecialchars($m['plan_name']) ?></td><td>₹<?= number_format($m['plan_price']) ?></td><td><?= htmlspecialchars($m['join_date']) ?></td><td><span class="status <?= strtolower($m['status']) ?>"><?= htmlspecialchars($m['status']) ?></span></td></tr><?php endforeach; ?></tbody></table></div></section><?php require "includes/footer.php"; ?>